import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { LK_CHANNEL, LK_MODELS } from "../src/lib/llm-channel-presets.js";

const payload = JSON.stringify({ channel: LK_CHANNEL, models: LK_MODELS });
const digest = createHash("sha256").update(payload).digest("hex");
const quote = (value) => JSON.stringify(value);
const java = `package com.chainlesschain.ide;

/** Generated by sync-lk-ide-presets.mjs; edit the CLI channel/catalog sources. */
public final class LkChannelCatalog {
    private LkChannelCatalog() {}
    public static final String SOURCE_SHA256 = ${quote(digest)};
    public static final String PRIMARY = ${quote(LK_CHANNEL.addresses.primary)};
    public static final String BACKUP = ${quote(LK_CHANNEL.addresses.backup)};
    public static final String PRICING_URL = ${quote(LK_CHANNEL.pricingUrl)};
    public static final class Model {
        public final String id, label, type, protocol;
        Model(String id, String label, String type, String protocol) {
            this.id = id; this.label = label; this.type = type; this.protocol = protocol;
        }
        public String toString() { return label + " (" + id + ")"; }
    }
    public static final Model[] MODELS = {
${LK_MODELS.map((m) => `        new Model(${[m.id, m.label, m.type, m.protocol].map(quote).join(", ")})`).join(",\n")}
    };
    public static String baseUrl(String protocol, boolean backup) {
        return (backup ? BACKUP : PRIMARY) + ("gemini".equals(protocol) ? "/v1beta" : "/v1");
    }
    public static boolean isEndpoint(String url) {
        String base = LlmConfig.normalizedBaseUrl(url);
        return base.equals(PRIMARY + "/v1") || base.equals(BACKUP + "/v1")
                || base.equals(PRIMARY + "/v1beta") || base.equals(BACKUP + "/v1beta");
    }
}
`;
const outputs = [
  ...[
    "../../../desktop-app-vue/src/main/llm/lk-public-catalog.cjs",
    "../../vscode-extension/src/vendor/lk-public-catalog.cjs",
  ].map((path) => [
    new URL(path, import.meta.url),
    readFileSync(
      new URL("../src/lib/lk-public-catalog.cjs", import.meta.url),
      "utf8",
    ),
  ]),
  [
    new URL(
      "../../../desktop-app-vue/src/main/llm/lk-account-api.js",
      import.meta.url,
    ),
    readFileSync(
      new URL("../src/lib/lk-account-api.cjs", import.meta.url),
      "utf8",
    ),
  ],
  [
    new URL(
      "../../web-panel/src/vendor/lk-channel-presets.json",
      import.meta.url,
    ),
    JSON.stringify(
      { sourceSha256: digest, channel: LK_CHANNEL, models: LK_MODELS },
      null,
      2,
    ) + "\n",
  ],
  [
    new URL(
      "../../vscode-extension/src/vendor/lk-channel-presets.json",
      import.meta.url,
    ),
    JSON.stringify(
      { sourceSha256: digest, channel: LK_CHANNEL, models: LK_MODELS },
      null,
      2,
    ) + "\n",
  ],
  [
    new URL(
      "../../jetbrains-plugin/src/main/java/com/chainlesschain/ide/LkChannelCatalog.java",
      import.meta.url,
    ),
    java,
  ],
];
for (const [path, expected] of outputs) {
  if (process.argv.includes("--check")) {
    const actual = readFileSync(path, "utf8").replaceAll("\r\n", "\n");
    const equal = path.pathname.endsWith(".json")
      ? JSON.stringify(JSON.parse(actual)) ===
        JSON.stringify(JSON.parse(expected))
      : actual === expected.replaceAll("\r\n", "\n");
    if (!equal) throw new Error(`Stale LK IDE catalog: ${path.pathname}`);
  } else {
    mkdirSync(new URL(".", path), { recursive: true });
    writeFileSync(path, expected);
  }
}
console.log("LK catalogs synchronized across CLI / Web / VS Code / JetBrains");
